}

fn toggle_story(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
    if self.open.as_ref().is_some_and(|open| open.name == name) {
        self.close_story(window, cx);
    } else {
        self.open_story(name, window, cx);
    }
}

/// Enter in an open story's title: it is kept, and another starts
/// beneath it, so a list can be written down without the mouse.
fn title_entered(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
    let Some((section, ix)) = self.find(name) else {
        return;
    };
    if self.sections[section_ix(section)][ix]
        .title
        .trim()
        .is_empty()
    {
        return;
    }
    // Beneath it, in Next sprint; from elsewhere, at Next sprint's end.
    let at = (section == Section::Next).then_some(ix + 1);
    self.new_story_at(at, window, cx);
}

/// Escape: closes what is open, one layer at a time: the mode picker or
/// a confirmation, the completions, a proposal being edited, the open
/// story, then the drafting panel. Whether there was anything to close.
fn escape(&mut self, window: &mut Window, cx: &mut Context<Self>) -> bool {
    if self.mode_menu.take().is_some() || self.confirm_delete.take().is_some() {
        cx.notify();
        return true;
    }
    if let Some(open) = &self.open
        && open.completion.read(cx).is_open()
    {
        open.completion.update(cx, |menu, cx| menu.hide(cx));
        return true;
    }
    if self.open_step.is_some() {
        self.close_step(window, cx);
        return true;
    }
    if let Some(editor) = self.editing.take() {
        self.focus_row(&editor.id, window, cx);
        return true;
    }
    if self.open.is_some() {
        self.close_story(window, cx);
        return true;
    }
    if self
        .drafting
        .as_ref()
        .is_some_and(|draft| draft.running.is_none())
        && self.proposals.is_empty()
    {
        self.drafting = None;
        self.focus.focus(window, cx);
        cx.notify();
        return true;
    }
    false
}

